CREATE OR REPLACE FUNCTION public.record_selected_export(_ids uuid[],_columns text[],_format text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR cardinality(_ids) NOT BETWEEN 1 AND 500 OR _format NOT IN ('csv','xlsx','pdf') THEN RAISE EXCEPTION 'Valid signed-in export required';END IF;INSERT INTO public.account_security_audit(user_id,event_type,result,details) VALUES(auth.uid(),'selected_trip_export','prepared',jsonb_build_object('count',cardinality(_ids),'columns',_columns,'format',_format));END $$;GRANT EXECUTE ON FUNCTION public.record_selected_export(uuid[],text[],text) TO authenticated;